// value of type *AIRunResponse.
func unmarshalAIRunResponseToAiAIRun(v *AIRunResponse) *ai.AIRun {
	res := &ai.AIRun{
		ID:                 *v.ID,
		Question:           *v.Question,
		Answer:             *v.Answer,
		Status:             *v.Status,
		Agent:              *v.Agent,
		Model:              *v.Model,
		InstructionVersion: *v.InstructionVersion,
		Origin:             *v.Origin,
		ErrorCode:          *v.ErrorCode,
		ToolCalls:          *v.ToolCalls,
		PromptTokens:       *v.PromptTokens,
		CompletionTokens:   *v.CompletionTokens,
		DurationMs:         *v.DurationMs,
		TraceID:            *v.TraceID,
		CorrelationID:      *v.CorrelationID,
		CausationID:        *v.CausationID,
		TriggerDepth:       *v.TriggerDepth,
		TriggerPolicy:      *v.TriggerPolicy,
		EventID:            *v.EventID,
		CreatedAt:          *v.CreatedAt,
		FinishedAt:         *v.FinishedAt,
	}
	res.Invocations = make([]*ai.CapabilityInvocation, len(v.Invocations))
	for i, val := range v.Invocations {
		if val == nil {
			res.Invocations[i] = nil
			continue
		}
		res.Invocations[i] = unmarshalCapabilityInvocationToAiCapabilityInvocation(val)
	}

	return res
}

